package filter

import (
	"container/list"
	"math"
	"sync"
)

// gaussianKernelVersion is bumped whenever GaussianKernel changes its
// algorithm (size formula, sigma scaling, normalization, ...). It is part of
// the cache key so a new binary can never serve a stale kernel generated by
// an older algorithm.
const gaussianKernelVersion uint16 = 1

// kernelRadiusQuant is the radius quantization factor: radii are bucketed to
// 1/kernelRadiusQuant (0.01) precision.
const kernelRadiusQuant = 100.0

// defaultKernelCacheCapacity is the maximum number of distinct kernels held
// by the package-level default cache.
const defaultKernelCacheCapacity = 64

// maxGaussianSigma bounds the sigma accepted when generating a Gaussian
// kernel. A kernel for sigma s has 2*ceil(3s)+1 float32 entries; without a
// cap an arbitrarily large (or Inf) radius would allocate unbounded memory
// or overflow the size computation. Radii above the cap are clamped to it,
// which keeps memory bounded (max ~240 KiB per kernel at sigma 10000).
const maxGaussianSigma = 10000.0

// kernelKey identifies a cached kernel: the quantized radius bucket together
// with the algorithm version that produced it.
type kernelKey struct {
	quantized int
	version   uint16
}

// CacheEventType enumerates the observable events of a kernel cache.
type CacheEventType int

const (
	// CacheEventHit is emitted when a get is served from the cache.
	CacheEventHit CacheEventType = iota

	// CacheEventMiss is emitted when a get does not find a cached entry
	// (including callers that join an in-flight generation via singleflight).
	CacheEventMiss

	// CacheEventGenerated is emitted when a new kernel has been built and
	// inserted into the cache.
	CacheEventGenerated

	// CacheEventEvicted is emitted once per entry removed by LRU eviction.
	CacheEventEvicted

	// CacheEventCleared is emitted when Clear empties the cache.
	CacheEventCleared
)

// CacheEvent describes one kernel cache transition for observability.
//
// Quantized and Version identify the kernel bucket (zero-valued for
// CacheEventCleared). KernelLen is the kernel length in float32 elements.
// Entries and Bytes describe removed storage (one entry on eviction, all
// entries on clear).
type CacheEvent struct {
	Type      CacheEventType
	Quantized int
	Version   uint16
	KernelLen int
	Entries   int
	Bytes     int64
}

// CacheObserver receives kernel cache events. Implementations must be safe
// for concurrent use; callbacks run outside the cache lock.
type CacheObserver interface {
	OnKernelCacheEvent(event CacheEvent)
}

// CacheObserverFunc adapts a function to the CacheObserver interface.
type CacheObserverFunc func(event CacheEvent)

// OnKernelCacheEvent implements CacheObserver.
func (f CacheObserverFunc) OnKernelCacheEvent(event CacheEvent) {
	f(event)
}

// CacheStats is a point-in-time snapshot of kernel cache counters.
type CacheStats struct {
	// Hits counts gets served from a cached entry.
	Hits int64

	// Misses counts gets without a cached entry (including singleflight
	// waiters that joined another goroutine's generation).
	Misses int64

	// Generations counts actual kernel generator invocations.
	Generations int64

	// Evictions counts entries removed by the LRU capacity policy.
	Evictions int64

	// Clears counts Clear calls, including repeated calls on an empty cache.
	Clears int64

	// Entries is the number of kernels currently held.
	Entries int

	// Bytes is the sum of cached kernel storage in bytes
	// (float32 elements * 4).
	Bytes int64

	// Capacity is the configured maximum number of entries (0 = pass-through).
	Capacity int

	// MaxSigma is the configured sigma clamp.
	MaxSigma float64
}

// KernelCacheOption customizes a kernel cache. Options only affect the cache
// instance they are passed to; the package-level default GaussianKernel
// results are unchanged.
type KernelCacheOption func(*kernelCache)

// WithKernelCacheCapacity sets the maximum number of cached kernels. A
// capacity of 0 turns the cache into a pass-through: every get generates a
// fresh kernel and nothing is retained or counted. Negative values are
// treated as 0.
func WithKernelCacheCapacity(capacity int) KernelCacheOption {
	return func(c *kernelCache) {
		if capacity < 0 {
			capacity = 0
		}
		c.capacity = capacity
	}
}

// WithKernelCacheMaxSigma overrides the sigma clamp. Non-positive or NaN
// values are ignored. An injected clamp only changes what the configured
// cache stores; direct GaussianKernel calls keep their default behavior.
func WithKernelCacheMaxSigma(maxSigma float64) KernelCacheOption {
	return func(c *kernelCache) {
		if maxSigma > 0 && !math.IsNaN(maxSigma) {
			c.maxSigma = maxSigma
		}
	}
}

// WithKernelCacheObserver attaches an observer for cache events.
func WithKernelCacheObserver(observer CacheObserver) KernelCacheOption {
	return func(c *kernelCache) {
		c.observer = observer
	}
}

// withKernelGenerator overrides the kernel generator. It is unexported and
// intended for fault-injection tests.
func withKernelGenerator(gen func(radius float64) []float32) KernelCacheOption {
	return func(c *kernelCache) {
		if gen != nil {
			c.generator = gen
		}
	}
}

// cacheEntry is one LRU node.
type cacheEntry struct {
	key     kernelKey
	kernel  []float32
	element *list.Element
}

// inflightGeneration coordinates concurrent gets for the same key: the first
// caller generates, every other caller waits and reuses the result.
type inflightGeneration struct {
	done     chan struct{}
	kernel   []float32
	panicked any
}

// kernelCache is a thread-safe, observable LRU cache of Gaussian kernels.
//
// Every get returns a private copy of the kernel: callers may freely mutate
// the returned slice, and LRU eviction can never invalidate a slice that a
// caller is still using.
type kernelCache struct {
	mu        sync.Mutex
	entries   map[kernelKey]*cacheEntry
	lru       *list.List
	inflight  map[kernelKey]*inflightGeneration
	capacity  int
	maxSigma  float64
	generator func(radius float64) []float32
	observer  CacheObserver
	stats     CacheStats
}

// defaultKernelCache backs CachedGaussianKernel.
var defaultKernelCache = newKernelCache()

// newKernelCache creates an LRU kernel cache. Without options it uses the
// default capacity and sigma clamp and generates kernels via GaussianKernel.
func newKernelCache(opts ...KernelCacheOption) *kernelCache {
	c := &kernelCache{
		entries:   make(map[kernelKey]*cacheEntry),
		lru:       list.New(),
		inflight:  make(map[kernelKey]*inflightGeneration),
		capacity:  defaultKernelCacheCapacity,
		maxSigma:  maxGaussianSigma,
		generator: GaussianKernel,
	}
	c.stats.Capacity = c.capacity
	c.stats.MaxSigma = c.maxSigma
	for _, opt := range opts {
		opt(c)
	}
	c.stats.Capacity = c.capacity
	c.stats.MaxSigma = c.maxSigma
	return c
}

// get returns a Gaussian kernel for radius. The returned slice is a private
// copy owned by the caller.
//
// Radius <= 0, NaN and +/-Inf return the single-element identity kernel
// [1]. Radii above the configured sigma clamp are clamped. With zero
// capacity the cache is a pass-through and retains nothing.
func (c *kernelCache) get(radius float64) []float32 {
	if !isFinitePositive(radius) {
		return []float32{1}
	}
	if radius > c.maxSigma {
		radius = c.maxSigma
	}
	key := kernelKey{
		quantized: quantizeRadius(radius),
		version:   gaussianKernelVersion,
	}

	c.mu.Lock()
	if c.capacity == 0 {
		c.mu.Unlock()
		return c.generator(radius)
	}
	if entry, ok := c.entries[key]; ok {
		c.lru.MoveToFront(entry.element)
		c.stats.Hits++
		kernel := cloneKernel(entry.kernel)
		c.mu.Unlock()
		c.notify(kernelEvent(CacheEventHit, key, len(kernel)))
		return kernel
	}
	if call, ok := c.inflight[key]; ok {
		// Singleflight: join the generation in progress.
		c.stats.Misses++
		c.mu.Unlock()
		return c.awaitGeneration(call)
	}
	call := &inflightGeneration{done: make(chan struct{})}
	c.inflight[key] = call
	c.stats.Misses++
	c.mu.Unlock()
	c.notify(kernelEvent(CacheEventMiss, key, 0))

	kernel, panicked := c.runGenerator(radius)
	if panicked != nil {
		c.failGeneration(key, call, panicked)
		panic(panicked)
	}

	events := c.completeGeneration(key, call, kernel)
	for _, event := range events {
		c.notify(event)
	}
	return cloneKernel(kernel)
}

// awaitGeneration waits for an in-flight generation owned by another
// goroutine and returns a private copy of its result.
func (c *kernelCache) awaitGeneration(call *inflightGeneration) []float32 {
	<-call.done
	if call.panicked != nil {
		panic(call.panicked)
	}
	return cloneKernel(call.kernel)
}

// runGenerator invokes the generator while converting a panic into a value.
func (c *kernelCache) runGenerator(radius float64) (kernel []float32, panicked any) {
	defer func() {
		panicked = recover()
	}()
	return c.generator(radius), nil
}

// failGeneration releases a failed in-flight generation and wakes waiters.
func (c *kernelCache) failGeneration(key kernelKey, call *inflightGeneration, panicked any) {
	c.mu.Lock()
	delete(c.inflight, key)
	call.panicked = panicked
	close(call.done)
	c.mu.Unlock()
}

// completeGeneration stores a freshly generated kernel, evicting LRU entries
// as needed, releases the singleflight slot, and returns the events to emit.
func (c *kernelCache) completeGeneration(
	key kernelKey, call *inflightGeneration, kernel []float32,
) []CacheEvent {
	c.mu.Lock()
	events := c.storeLocked(key, kernel)
	delete(c.inflight, key)
	call.kernel = kernel
	close(call.done)
	c.mu.Unlock()
	return events
}

// storeLocked inserts kernel under key, evicting oldest entries while the
// cache is at capacity, and updates counters.
func (c *kernelCache) storeLocked(key kernelKey, kernel []float32) []CacheEvent {
	var events []CacheEvent

	for len(c.entries) >= c.capacity {
		oldest := c.lru.Back()
		if oldest == nil {
			break
		}
		evicted := c.lru.Remove(oldest).(*cacheEntry)
		delete(c.entries, evicted.key)
		c.stats.Evictions++
		c.stats.Bytes -= kernelBytes(len(evicted.kernel))
		events = append(events, kernelEvent(CacheEventEvicted, evicted.key, len(evicted.kernel)))
	}

	entry := &cacheEntry{key: key, kernel: kernel}
	entry.element = c.lru.PushFront(entry)
	c.entries[key] = entry
	c.stats.Generations++
	c.stats.Bytes += kernelBytes(len(kernel))

	events = append(events, kernelEvent(CacheEventGenerated, key, len(kernel)))
	return events
}

// Clear removes all cached entries. It is safe to call repeatedly, including
// on an empty cache: every call increments the Clears counter and emits a
// CacheEventCleared event. Kernels already handed out are private copies and
// remain valid. Generations in flight complete normally and may re-insert
// entries after the clear.
func (c *kernelCache) Clear() {
	c.mu.Lock()
	removed := len(c.entries)
	bytes := c.stats.Bytes
	c.entries = make(map[kernelKey]*cacheEntry)
	c.lru.Init()
	c.stats.Bytes = 0
	c.stats.Clears++
	c.mu.Unlock()

	c.notify(CacheEvent{
		Type:    CacheEventCleared,
		Entries: removed,
		Bytes:   bytes,
	})
}

// Stats returns a copy of the current counters.
func (c *kernelCache) Stats() CacheStats {
	c.mu.Lock()
	stats := c.stats
	stats.Entries = len(c.entries)
	c.mu.Unlock()
	return stats
}

// notify emits an event when an observer is attached.
func (c *kernelCache) notify(event CacheEvent) {
	if c.observer != nil {
		c.observer.OnKernelCacheEvent(event)
	}
}

// CachedGaussianKernel returns a cached Gaussian kernel for radius. The
// returned slice is a private copy: mutating it never affects subsequent
// calls or other goroutines. Behavior for non-positive and non-finite radii
// matches GaussianKernel.
func CachedGaussianKernel(radius float64) []float32 {
	return defaultKernelCache.get(radius)
}

// quantizeRadius maps a radius to its 0.01-precision bucket.
func quantizeRadius(radius float64) int {
	return int(math.Round(radius * kernelRadiusQuant))
}

// isFinitePositive reports whether radius is a finite, strictly positive
// number.
func isFinitePositive(radius float64) bool {
	return radius > 0 && !math.IsNaN(radius) && !math.IsInf(radius, 0)
}

// cloneKernel returns a private copy of kernel.
func cloneKernel(kernel []float32) []float32 {
	return append([]float32(nil), kernel...)
}

// kernelBytes returns the storage size of a kernel in bytes.
func kernelBytes(kernelLen int) int64 {
	return int64(kernelLen) * 4
}

// kernelEvent builds an event carrying the key and kernel length.
func kernelEvent(eventType CacheEventType, key kernelKey, kernelLen int) CacheEvent {
	return CacheEvent{
		Type:      eventType,
		Quantized: key.quantized,
		Version:   key.version,
		KernelLen: kernelLen,
	}
}
